package com.example.studentcourseregistration.model;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * Student Model Class
 * Represents a student registered for a course in the system.
 * Plain Java class (POJO) without Lombok for beginner clarity.
 */
public class Student {

    // Unique identifier for the student (Auto-generated by service)
    private Long studentId;

    // Full name of the student
    @NotBlank(message = "Student name cannot be empty")
    private String studentName;

    // Name of the course the student is registering for
    @NotBlank(message = "Course name cannot be empty")
    private String courseName;

    // Student email address with format and not-blank validation
    @NotBlank(message = "Email cannot be empty")
    @Email(message = "Enter valid email")
    private String email;

    // Student age (must be at least 18)
    @NotNull(message = "Age cannot be null")
    @Min(value = 18, message = "Age must be above 18")
    private Integer age;

    /**
     * Default constructor (No-argument constructor).
     * Required by Spring and Jackson to deserialize JSON into a Student object.
     */
    public Student() {
    }

    /**
     * Parameterized constructor.
     * Used to create a Student object with all fields initialized.
     *
     * @param studentId   the unique ID of the student
     * @param studentName the name of the student
     * @param courseName  the course enrolled in
     * @param email       the student's email
     * @param age         the student's age
     */
    public Student(Long studentId, String studentName, String courseName, String email, Integer age) {
        this.studentId = studentId;
        this.studentName = studentName;
        this.courseName = courseName;
        this.email = email;
        this.age = age;
    }

    // --- Getters and Setters ---

    public Long getStudentId() {
        return studentId;
    }

    public void setStudentId(Long studentId) {
        this.studentId = studentId;
    }

    public String getStudentName() {
        return studentName;
    }

    public void setStudentName(String studentName) {
        this.studentName = studentName;
    }

    public String getCourseName() {
        return courseName;
    }

    public void setCourseName(String courseName) {
        this.courseName = courseName;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public Integer getAge() {
        return age;
    }

    public void setAge(Integer age) {
        this.age = age;
    }

    @Override
    public String toString() {
        return "Student{" +
                "studentId=" + studentId +
                ", studentName='" + studentName + '\'' +
                ", courseName='" + courseName + '\'' +
                ", email='" + email + '\'' +
                ", age=" + age +
                '}';
    }
}
